export function validateCT_ApplicationNonVisualDrawingProps(value: unknown, path = 'CT_ApplicationNonVisualDrawingProps'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['ph'] === undefined) {
  } else {
    issues.push(...validateCT_Placeholder(v['ph'], path + '.ph'));
  }
  if (v['media'] === undefined) {
  } else {
    if (v['media'] && typeof v['media'] === 'object') {
      const item = v['media'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'audioCd') issues.push(...validateCT_AudioCD(item.value, path + '.media' + '.value'));
        if (item.kind === 'wavAudioFile') issues.push(...validateCT_EmbeddedWAVAudioFile(item.value, path + '.media' + '.value'));
        if (item.kind === 'audioFile') issues.push(...validateCT_AudioFile(item.value, path + '.media' + '.value'));
        if (item.kind === 'videoFile') issues.push(...validateCT_VideoFile(item.value, path + '.media' + '.value'));
        if (item.kind === 'quickTimeFile') issues.push(...validateCT_QuickTimeFile(item.value, path + '.media' + '.value'));
        if ('audioCd' !== item.kind && 'wavAudioFile' !== item.kind && 'audioFile' !== item.kind && 'videoFile' !== item.kind && 'quickTimeFile' !== item.kind) issues.push(issue(path + '.media', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['custDataLst'] === undefined) {
  } else {
    issues.push(...validateCT_CustomerDataList(v['custDataLst'], path + '.custDataLst'));
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionList(v['extLst'], path + '.extLst'));
  }
  if (v['isPhoto'] === undefined) {
  } else {
    if (!validBuiltin(v['isPhoto'], 'xsd:boolean')) issues.push(issue(path + '.isPhoto', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['userDrawn'] === undefined) {
  } else {
    if (!validBuiltin(v['userDrawn'], 'xsd:boolean')) issues.push(issue(path + '.userDrawn', 'invalid-value', 'invalid xsd:boolean'));
  }
  return issues;
}

