          if (item.kind === 'bldDgm') issues.push(...validateCT_TLBuildDiagram(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'bldOleChart') issues.push(...validateCT_TLOleBuildChart(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'bldGraphic') issues.push(...validateCT_TLGraphicalObjectBuild(item.value, path + '.content[' + i + ']' + '.value'));
