export function validateCT_GroupShape(value: unknown, path = 'CT_GroupShape'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['nvGrpSpPr'] === undefined) {
    issues.push(issue(path + '.nvGrpSpPr', 'missing-required', 'required slot is absent'));
  } else {
    issues.push(...validateCT_GroupShapeNonVisual(v['nvGrpSpPr'], path + '.nvGrpSpPr'));
  }
  if (v['grpSpPr'] === undefined) {
    issues.push(issue(path + '.grpSpPr', 'missing-required', 'required slot is absent'));
  } else {
    issues.push(...validateCT_GroupShapeProperties(v['grpSpPr'], path + '.grpSpPr'));
  }
  if (!Array.isArray(v['content'])) {
  } else {
    for (let i = 0; i < (v['content'] as readonly unknown[]).length; i += 1) {
      if ((v['content'] as readonly unknown[])[i] && typeof (v['content'] as readonly unknown[])[i] === 'object') {
        const item = (v['content'] as readonly unknown[])[i] as { kind?: unknown; value?: unknown };
        if (item.kind !== '$raw') {
          if (item.kind === 'sp') issues.push(...validateCT_Shape(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'grpSp') issues.push(...validateCT_GroupShape(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'graphicFrame') issues.push(...validateCT_GraphicalObjectFrame(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'cxnSp') issues.push(...validateCT_Connector(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'pic') issues.push(...validateCT_Picture(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'contentPart') issues.push(...validateCT_Rel(item.value, path + '.content[' + i + ']' + '.value'));
          if ('sp' !== item.kind && 'grpSp' !== item.kind && 'graphicFrame' !== item.kind && 'cxnSp' !== item.kind && 'pic' !== item.kind && 'contentPart' !== item.kind) issues.push(issue(path + '.content[' + i + ']', 'invalid-value', 'unknown choice alternative'));
        }
      }
    }
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionListModify(v['extLst'], path + '.extLst'));
  }
  return issues;
}

