export function validateCT_OleObject(value: unknown, path = 'CT_OleObject'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
    issues.push(issue(path + '.content', 'missing-required', 'required slot is absent'));
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'embed') issues.push(...validateCT_OleObjectEmbed(item.value, path + '.content' + '.value'));
        if (item.kind === 'link') issues.push(...validateCT_OleObjectLink(item.value, path + '.content' + '.value'));
        if ('embed' !== item.kind && 'link' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['pic'] === undefined) {
  } else {
    issues.push(...validateCT_Picture(v['pic'], path + '.pic'));
  }
  if (v['spid'] === undefined) {
  } else {
    issues.push(...validateST_ShapeID(v['spid'], path + '.spid'));
  }
  if (v['name'] === undefined) {
  } else {
    if (!validBuiltin(v['name'], 'xsd:string')) issues.push(issue(path + '.name', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['showAsIcon'] === undefined) {
  } else {
    if (!validBuiltin(v['showAsIcon'], 'xsd:boolean')) issues.push(issue(path + '.showAsIcon', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['id'] === undefined) {
  } else {
    issues.push(...validateST_RelationshipId(v['id'], path + '.id'));
  }
  if (v['imgW'] === undefined) {
  } else {
    issues.push(...validateST_PositiveCoordinate32(v['imgW'], path + '.imgW'));
  }
  if (v['imgH'] === undefined) {
  } else {
    issues.push(...validateST_PositiveCoordinate32(v['imgH'], path + '.imgH'));
  }
  if (v['progId'] === undefined) {
  } else {
    if (!validBuiltin(v['progId'], 'xsd:string')) issues.push(issue(path + '.progId', 'invalid-value', 'invalid xsd:string'));
  }
  return issues;
}

