export function validateCT_ShowProperties(value: unknown, path = 'CT_ShowProperties'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['showType'] === undefined) {
  } else {
    if (v['showType'] && typeof v['showType'] === 'object') {
      const item = v['showType'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'present') issues.push(...validateCT_Empty(item.value, path + '.showType' + '.value'));
        if (item.kind === 'browse') issues.push(...validateCT_ShowInfoBrowse(item.value, path + '.showType' + '.value'));
        if (item.kind === 'kiosk') issues.push(...validateCT_ShowInfoKiosk(item.value, path + '.showType' + '.value'));
        if ('present' !== item.kind && 'browse' !== item.kind && 'kiosk' !== item.kind) issues.push(issue(path + '.showType', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['slideListChoice'] === undefined) {
  } else {
    if (v['slideListChoice'] && typeof v['slideListChoice'] === 'object') {
      const item = v['slideListChoice'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'sldAll') issues.push(...validateCT_Empty(item.value, path + '.slideListChoice' + '.value'));
        if (item.kind === 'sldRg') issues.push(...validateCT_IndexRange(item.value, path + '.slideListChoice' + '.value'));
        if (item.kind === 'custShow') issues.push(...validateCT_CustomShowId(item.value, path + '.slideListChoice' + '.value'));
        if ('sldAll' !== item.kind && 'sldRg' !== item.kind && 'custShow' !== item.kind) issues.push(issue(path + '.slideListChoice', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['penClr'] === undefined) {
  } else {
    issues.push(...validateCT_Color(v['penClr'], path + '.penClr'));
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionList(v['extLst'], path + '.extLst'));
  }
  if (v['loop'] === undefined) {
  } else {
    if (!validBuiltin(v['loop'], 'xsd:boolean')) issues.push(issue(path + '.loop', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['showNarration'] === undefined) {
  } else {
    if (!validBuiltin(v['showNarration'], 'xsd:boolean')) issues.push(issue(path + '.showNarration', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['showAnimation'] === undefined) {
  } else {
    if (!validBuiltin(v['showAnimation'], 'xsd:boolean')) issues.push(issue(path + '.showAnimation', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['useTimings'] === undefined) {
  } else {
    if (!validBuiltin(v['useTimings'], 'xsd:boolean')) issues.push(issue(path + '.useTimings', 'invalid-value', 'invalid xsd:boolean'));
  }
  return issues;
}

