export function validateCT_SlideTransition(value: unknown, path = 'CT_SlideTransition'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'blinds') issues.push(...validateCT_OrientationTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'checker') issues.push(...validateCT_OrientationTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'circle') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'dissolve') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'comb') issues.push(...validateCT_OrientationTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'cover') issues.push(...validateCT_EightDirectionTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'cut') issues.push(...validateCT_OptionalBlackTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'diamond') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'fade') issues.push(...validateCT_OptionalBlackTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'newsflash') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'plus') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'pull') issues.push(...validateCT_EightDirectionTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'push') issues.push(...validateCT_SideDirectionTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'random') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'randomBar') issues.push(...validateCT_OrientationTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'split') issues.push(...validateCT_SplitTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'strips') issues.push(...validateCT_CornerDirectionTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'wedge') issues.push(...validateCT_Empty(item.value, path + '.content' + '.value'));
        if (item.kind === 'wheel') issues.push(...validateCT_WheelTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'wipe') issues.push(...validateCT_SideDirectionTransition(item.value, path + '.content' + '.value'));
        if (item.kind === 'zoom') issues.push(...validateCT_InOutTransition(item.value, path + '.content' + '.value'));
        if ('blinds' !== item.kind && 'checker' !== item.kind && 'circle' !== item.kind && 'dissolve' !== item.kind && 'comb' !== item.kind && 'cover' !== item.kind && 'cut' !== item.kind && 'diamond' !== item.kind && 'fade' !== item.kind && 'newsflash' !== item.kind && 'plus' !== item.kind && 'pull' !== item.kind && 'push' !== item.kind && 'random' !== item.kind && 'randomBar' !== item.kind && 'split' !== item.kind && 'strips' !== item.kind && 'wedge' !== item.kind && 'wheel' !== item.kind && 'wipe' !== item.kind && 'zoom' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['sndAc'] === undefined) {
  } else {
    issues.push(...validateCT_TransitionSoundAction(v['sndAc'], path + '.sndAc'));
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionListModify(v['extLst'], path + '.extLst'));
  }
  if (v['spd'] === undefined) {
  } else {
    issues.push(...validateST_TransitionSpeed(v['spd'], path + '.spd'));
  }
  if (v['advClick'] === undefined) {
  } else {
    if (!validBuiltin(v['advClick'], 'xsd:boolean')) issues.push(issue(path + '.advClick', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['advTm'] === undefined) {
  } else {
    if (!validBuiltin(v['advTm'], 'xsd:unsignedInt')) issues.push(issue(path + '.advTm', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  return issues;
}

